public class PackagerGameTests {
    private static final BlockPos P=new BlockPos(3,3,3),TARGET=P.north();
    private static PackagerBlockEntity packager(GameTestHelper h){h.setBlock(P,AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));return h.getBlockEntity(P,PackagerBlockEntity.class);}
    private static RepackagerBlockEntity repackager(GameTestHelper h){h.setBlock(P,AllBlocks.REPACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));return h.getBlockEntity(P,RepackagerBlockEntity.class);}
    private static ChestBlockEntity chest(GameTestHelper h){h.setBlock(TARGET,Blocks.CHEST);return h.getBlockEntity(TARGET,ChestBlockEntity.class);}
    private static ItemStack box(ItemStack... items){return PackageItem.containing(List.of(items));}
    private static void tick(PackagerBlockEntity packager,int times){for(int i=0;i<times;i++)PackagerBlockEntity.tick(packager.getLevel(),packager.getBlockPos(),packager.getBlockState(),packager);}
    private static int count(ChestBlockEntity chest,Item item){int count=0;for(int i=0;i<chest.getContainerSize();i++)if(chest.getItem(i).is(item))count+=chest.getItem(i).getCount();return count;}
    private static Player player(GameTestHelper h,ItemStack held){var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(h.absolutePos(P)).add(0,0,2));player.setItemInHand(InteractionHand.MAIN_HAND,held);return player;}
    @GameTest public void committedTransferCanRaiseRedstoneWithoutOpeningAnotherTransaction(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.APPLE,12));var packager=packager(h);try(var tx=Transaction.openOuter()){tx.addOuterCloseCallback(result->{if(result.wasCommitted())h.setBlock(P.east(),Blocks.REDSTONE_BLOCK);});tx.commit();}tick(packager,1);h.assertTrue(PackageItem.isPackage(packager.heldBox),"Committed redstone edge packages on the next safe tick");h.assertValueEqual(PackageItem.getContents(packager.heldBox).getFirst().getCount(),12,"One owned contents batch");h.assertTrue(source.isEmpty(),"Source extracted once");h.succeed();}
    @GameTest public void originalSurvivalRecipesCreateCardboardPackagerAndConversion(GameTestHelper h){var manager=h.getLevel().getServer().getRecipeManager();var input=net.minecraft.world.item.crafting.CraftingInput.of(3,3,List.of(ItemStack.EMPTY,new ItemStack(Items.IRON_INGOT),ItemStack.EMPTY,new ItemStack(Items.IRON_INGOT),new ItemStack(AllBlocks.CARDBOARD_BLOCK),new ItemStack(Items.IRON_INGOT),new ItemStack(Items.REDSTONE),new ItemStack(Items.IRON_INGOT),new ItemStack(Items.REDSTONE)));var recipe=manager.getRecipeFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING,input,h.getLevel()).orElseThrow();h.assertTrue(recipe.value().assemble(input).is(AllBlocks.PACKAGER.asItem()),"Original iron/redstone/cardboard recipe");var conversion=net.minecraft.world.item.crafting.CraftingInput.of(1,1,List.of(new ItemStack(AllBlocks.PACKAGER)));h.assertTrue(manager.getRecipeFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING,conversion,h.getLevel()).orElseThrow().value().assemble(conversion).is(AllBlocks.REPACKAGER.asItem()),"Original conversion recipe");h.succeed();}
    @GameTest public void addonUnpackingCanMutateWorkingListAndFailureAbortsItsStorageChanges(GameTestHelper h){
        h.setBlock(TARGET,Blocks.IRON_BLOCK);h.setBlock(TARGET.above(),Blocks.CHEST);var chest=h.getBlockEntity(TARGET.above(),ChestBlockEntity.class);var packager=packager(h);var parcel=box(new ItemStack(Items.APPLE,8));var pos=h.absolutePos(TARGET);PackagerTestFixtures.HANDLERS.put(pos,(level,target,state,side,items,order,tx)->{var storage=com.simibubi.create.content.logistics.funnel.FunnelTransfer.find(level,target.above(),Direction.UP);storage.insert(ItemVariant.of(Items.APPLE),3,tx);items.clear();return false;});h.assertFalse(packager.unwrapBox(parcel,false),"Custom failure propagates");h.assertTrue(chest.isEmpty(),"Custom tentative insertion rolled back");h.assertValueEqual(PackageItem.getContents(parcel).getFirst().getCount(),8,"Custom working-list mutation leaves original component intact");h.assertValueEqual(packager.animationTicks,0,"Custom failure has no animation");h.succeed();
    }
    @GameTest public void nativeClientPacketOmitsStockSummaryAndOutputQueue(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.APPLE,12));var packager=packager(h);packager.getAvailableItems();packager.queuedExitingPackages.add(new BigItemStack(box(new ItemStack(Items.DIAMOND)),2));var client=packager.getUpdateTag(h.getLevel().registryAccess());h.assertFalse(client.contains("QueuedExitingPackages")||client.contains("LastSummary"),"Server-only logistics state stays out of visual packets");var disk=packager.saveWithFullMetadata(h.getLevel().registryAccess());h.assertTrue(disk.contains("QueuedExitingPackages")&&disk.contains("LastSummary"),"Full state remains on disk");h.succeed();}
    @GameTest public void repackageRecipeContextsSplitIntoCountedFullCraftBoxes(GameTestHelper h){
        var source=chest(h);var fragment=box(new ItemStack(Items.APPLE,3),new ItemStack(Items.DIAMOND,2));PackageItem.addAddress(fragment,"Craft Warehouse");var recipe=new PackageOrder(List.of(new BigItemStack(new ItemStack(Items.APPLE),1),new BigItemStack(new ItemStack(Items.DIAMOND),1)));var context=new PackageOrderWithCrafts(new PackageOrder(List.of(new BigItemStack(new ItemStack(Items.APPLE),3),new BigItemStack(new ItemStack(Items.DIAMOND),2))),List.of(new PackageOrderWithCrafts.CraftingEntry(recipe,2)));PackageItem.setOrder(fragment,88,0,true,0,true,context);source.setItem(0,fragment);var repackager=repackager(h);repackager.attemptToSend(null);
        h.assertTrue(source.isEmpty(),"Fragment source relinquishes all five materials exactly once");h.assertValueEqual(repackager.queuedExitingPackages.size(),2,"Recipe batch plus residual batch");var crafts=repackager.queuedExitingPackages.getFirst();h.assertValueEqual(crafts.count,2,"Two identical recipe packages represented once with count two");h.assertValueEqual(PackageItem.getOrderContext(crafts.stack),PackageOrderWithCrafts.singleRecipe(recipe.stacks()),"Each crafted package retains the exact recipe placement information");
        var craftSlots=PackageItem.getContents(crafts.stack);h.assertTrue(craftSlots.get(0).is(Items.APPLE)&&craftSlots.get(0).getCount()==1&&craftSlots.get(1).is(Items.DIAMOND)&&craftSlots.get(1).getCount()==1&&craftSlots.stream().skip(2).allMatch(ItemStack::isEmpty),"Counted package contains exactly one complete craft in its original slots");
        var residual=repackager.queuedExitingPackages.getLast();h.assertValueEqual(residual.count,1,"One residual box");h.assertValueEqual(PackageItem.getOrderId(residual.stack),88,"Residual retains its original order");var residualSlots=PackageItem.getContents(residual.stack);h.assertTrue(residualSlots.getFirst().is(Items.APPLE)&&residualSlots.getFirst().getCount()==1&&residualSlots.stream().skip(1).allMatch(ItemStack::isEmpty),"Residual is exactly the one unused apple");
        int total=0,apples=0,diamonds=0;for(var output:repackager.queuedExitingPackages){h.assertTrue(output.count>0,"No zero-count output owner");h.assertValueEqual(PackageItem.getAddress(output.stack),"Craft Warehouse","Every output retains destination");for(var item:PackageItem.getContents(output.stack)){int count=item.getCount()*output.count;total+=count;if(item.is(Items.APPLE))apples+=count;if(item.is(Items.DIAMOND))diamonds+=count;}}
        h.assertValueEqual(total,5,"All five items represented including residual apple");h.assertValueEqual(apples,3,"All three source apples conserved");h.assertValueEqual(diamonds,2,"Both source diamonds conserved");h.succeed();
    }
    @GameTest public void destructionDropsHeldAndQueuedPackagesOnceButNeverInsertedVisual(GameTestHelper h){var destination=chest(h);var packager=packager(h);packager.heldBox=box(new ItemStack(Items.APPLE,6));packager.queuedExitingPackages.add(new BigItemStack(box(new ItemStack(Items.DIAMOND,4)),2));packager.previouslyUnwrapped=box(new ItemStack(Items.GOLD_INGOT,9));packager.animationTicks=10;h.setBlock(P,Blocks.AIR);var entities=h.getLevel().getEntitiesOfClass(PackageEntity.class,new AABB(h.absolutePos(P)).inflate(2));h.assertValueEqual(entities.size(),3,"Held and two queued packages dropped");int apples=0,diamonds=0,gold=0;for(var entity:entities)for(var stack:PackageItem.getContents(entity.getBox())){if(stack.is(Items.APPLE))apples+=stack.getCount();if(stack.is(Items.DIAMOND))diamonds+=stack.getCount();if(stack.is(Items.GOLD_INGOT))gold+=stack.getCount();}h.assertValueEqual(apples,6,"Held contents once");h.assertValueEqual(diamonds,8,"Queue multiplicity retained");h.assertValueEqual(gold,0,"Inserted visual has no inventory ownership");h.succeed();}
    @GameTest public void unloadingBlockEntityNeverDropsItsOwnedPackages(GameTestHelper h){chest(h);var packager=packager(h);packager.heldBox=box(new ItemStack(Items.APPLE,6));packager.setRemoved();packager.clearRemoved();h.assertTrue(h.getLevel().getEntitiesOfClass(PackageEntity.class,new AABB(h.absolutePos(P)).inflate(2)).isEmpty(),"Unload produces no duplicate drops");h.assertTrue(PackageItem.isPackage(packager.heldBox),"Unload retains contents for persistence");h.succeed();}
    @GameTest public void realRedstoneEdgePacksAndComparatorTracksCycleAndOutput(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.APPLE,12));var packager=packager(h);h.setBlock(P.east(),Blocks.REDSTONE_BLOCK);h.assertTrue(packager.getBlockState().getValue(PackagerBlock.POWERED),"Native neighbor signal powers packager");h.assertTrue(PackageItem.isPackage(packager.heldBox),"Rising edge creates box");h.assertValueEqual(packager.getBlockState().getAnalogOutputSignal(h.getLevel(),h.absolutePos(P),Direction.NORTH),15,"Comparator powered during cycle");tick(packager,20);try(var tx=Transaction.openOuter()){packager.inventory.extract(ItemVariant.of(packager.heldBox),1,tx);tx.commit();}h.assertValueEqual(packager.getBlockState().getAnalogOutputSignal(h.getLevel(),h.absolutePos(P),Direction.NORTH),0,"Empty output clears comparator");h.succeed();}
    @GameTest(maxTicks=80) public void orderedUnpackingStartsRealMechanicalCraftingAfterCommit(GameTestHelper h){
        var state=AllBlocks.MECHANICAL_CRAFTER.defaultBlockState().setValue(MechanicalCrafterBlock.HORIZONTAL_FACING,Direction.SOUTH).setValue(MechanicalCrafterBlock.POINTING,net.createmod.catnip.math.Pointing.RIGHT);h.setBlock(TARGET,state);h.setBlock(TARGET.above(),state.setValue(MechanicalCrafterBlock.POINTING,net.createmod.catnip.math.Pointing.DOWN));ConnectedInputHandler.toggleConnection(h.getLevel(),h.absolutePos(TARGET),h.absolutePos(TARGET.above()));h.setBlock(TARGET.west(),AllBlocks.COGWHEEL.defaultBlockState().setValue(com.simibubi.create.content.kinetics.simpleRelays.CogWheelBlock.AXIS,Direction.Axis.Z));var motor=TARGET.west().north();h.setBlock(motor,AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(com.simibubi.create.content.kinetics.motor.CreativeMotorBlock.FACING,Direction.SOUTH));h.getBlockEntity(motor,com.simibubi.create.content.kinetics.base.KineticBlockEntity.class).setGeneratedSpeed(256);h.setBlock(TARGET.east(),AllBlocks.DEPOT);var packager=packager(h);var box=box(new ItemStack(Items.OAK_PLANKS,2));PackageItem.addOrderContext(box,PackageOrderWithCrafts.singleRecipe(List.of(new BigItemStack(new ItemStack(Items.OAK_PLANKS),1),new BigItemStack(new ItemStack(Items.OAK_PLANKS),1))));
        h.runAfterDelay(2,()->{h.assertTrue(packager.unwrapBox(box,false),"Full ordered delivery");});h.succeedWhen(()->{var depot=h.getBlockEntity(TARGET.east(),com.simibubi.create.content.logistics.depot.DepotBlockEntity.class);h.assertTrue(depot.getHeldItem().is(Items.STICK)&&depot.getHeldItem().getCount()==4,"Native transaction commit drives real sticks recipe");});
    }
    @GameTest public void ordinaryPackagingFillsNineSlotsAndConservesInventory(GameTestHelper h){
        var source=chest(h);for(int i=0;i<12;i++)source.setItem(i,new ItemStack(Items.APPLE,64));var packager=packager(h);packager.attemptToSend(null);var contents=PackageItem.getContents(packager.heldBox);h.assertValueEqual(contents.stream().mapToInt(ItemStack::getCount).sum(),576,"Nine stacks packed");h.assertValueEqual(count(source,Items.APPLE),192,"Unpacked balance remains");h.assertValueEqual(packager.animationTicks,20,"Outbound animation starts");try(var tx=Transaction.openOuter()){h.assertValueEqual(packager.inventory.extract(ItemVariant.of(packager.heldBox),1,tx),0L,"Cannot extract through animation");}tick(packager,20);h.assertValueEqual(packager.animationTicks,0,"Cycle completes");h.succeed();
    }
    @GameTest public void bulkyContainerTravelsAloneWithoutPackingOtherContents(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.SHULKER_BOX));source.setItem(1,new ItemStack(Items.APPLE,32));var packager=packager(h);packager.attemptToSend(null);h.assertTrue(PackageItem.getContents(packager.heldBox).getFirst().is(Items.SHULKER_BOX),"Bulky shulker boxed by itself");h.assertValueEqual(PackageItem.getContents(packager.heldBox).stream().filter(item->!item.isEmpty()).count(),1L,"No other cargo in bulky package");h.assertValueEqual(count(source,Items.APPLE),32,"Ordinary cargo remains");h.succeed();}
    @GameTest public void existingPackageIsForwardedAndSignAddressReplacesOldAddress(GameTestHelper h){var source=chest(h);var forwarded=box(new ItemStack(Items.DIAMOND,12));PackageItem.addAddress(forwarded,"Old");source.setItem(0,forwarded);var packager=packager(h);packager.signBasedAddress="New";packager.attemptToSend(null);h.assertValueEqual(PackageItem.getAddress(packager.heldBox),"New","Readdressed without nesting");h.assertValueEqual(PackageItem.getContents(packager.heldBox).getFirst().getCount(),12,"Original contents kept");h.assertTrue(source.isEmpty(),"One package extracted");h.succeed();}
    @GameTest public void unpackingSimulationAndNestedAbortNeverChangeContainerOrAnimation(GameTestHelper h){var destination=chest(h);var packager=packager(h);var box=box(new ItemStack(Items.APPLE,12),new ItemStack(Items.DIAMOND,3));h.assertTrue(packager.unwrapBox(box,true),"Simulation can fit");h.assertTrue(destination.isEmpty()&&packager.animationTicks==0,"Simulation rollback");try(var tx=Transaction.openOuter()){h.assertValueEqual(packager.inventory.insert(ItemVariant.of(box),1,tx),1L,"Nested unpack accepted");h.assertValueEqual(count(destination,Items.APPLE),12,"Tentative contents visible inside transaction");}h.assertTrue(destination.isEmpty()&&packager.animationTicks==0,"Outer abort restores storage and machine");h.assertTrue(packager.previouslyUnwrapped.isEmpty(),"No phantom inserted box");h.succeed();}
    @GameTest public void wholeBoxMustFitIncludingEveryDistinctVariant(GameTestHelper h){var destination=chest(h);for(int i=0;i<27;i++)destination.setItem(i,new ItemStack(Items.STONE,64));destination.setItem(0,new ItemStack(Items.APPLE,60));var packager=packager(h);var box=box(new ItemStack(Items.APPLE,4),new ItemStack(Items.DIAMOND));h.assertFalse(packager.unwrapBox(box,false),"Full destination refuses entire box");h.assertValueEqual(count(destination,Items.APPLE),60,"Earlier fitting item rolled back");h.assertValueEqual(packager.animationTicks,0,"Rejected delivery has no animation");h.assertTrue(PackageItem.getContents(box).getFirst().getCount()==4,"Caller retains original cargo");h.succeed();}
    @GameTest public void committedUnpackingProducesExactlyOneInboundAnimation(GameTestHelper h){var destination=chest(h);var packager=packager(h);var box=box(new ItemStack(Items.APPLE,12));try(var tx=Transaction.openOuter()){h.assertValueEqual(packager.inventory.insert(ItemVariant.of(box),3,tx),1L,"Only one box per animation");tx.commit();}h.assertValueEqual(count(destination,Items.APPLE),12,"One contents batch");h.assertTrue(packager.animationInward&&packager.animationTicks==20,"Inbound cycle");try(var tx=Transaction.openOuter()){h.assertValueEqual(packager.inventory.insert(ItemVariant.of(box),1,tx),0L,"Busy machine rejects second box");}h.succeed();}
    @GameTest public void emptyPackageIsConsumedWithoutAnimationOrTargetInventory(GameTestHelper h){var packager=packager(h);h.assertTrue(packager.unwrapBox(PackageStyles.getDefaultBox(),false),"Empty box succeeds without target");h.assertValueEqual(packager.animationTicks,0,"No empty animation");h.succeed();}
    @GameTest public void outputExtractionRollsBackAndDoesNotUnpackHeldBox(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.DIAMOND,7));var packager=packager(h);packager.attemptToSend(null);tick(packager,20);var before=packager.heldBox.copy();try(var tx=Transaction.openOuter()){h.assertValueEqual(packager.inventory.extract(ItemVariant.of(before),1,tx),1L,"Ready outbound box extractable");h.assertTrue(packager.heldBox.isEmpty(),"Tentative extraction");}h.assertTrue(ItemStack.isSameItemSameComponents(before,packager.heldBox),"Abort restores box metadata");try(var tx=Transaction.openOuter()){h.assertValueEqual(packager.inventory.extract(ItemVariant.of(before),1,tx),1L,"Extraction commit");tx.commit();}h.assertTrue(packager.heldBox.isEmpty()&&source.isEmpty(),"Box ownership moved, contents not returned");h.succeed();}
    @GameTest public void signAddressReadsFrontThenBackAndSkipsBlankLines(GameTestHelper h){var packager=packager(h);h.setBlock(P.east(),Blocks.OAK_SIGN);var sign=h.getBlockEntity(P.east(),SignBlockEntity.class);var front=List.<Component>of(Component.literal(" North "),Component.empty(),Component.literal(" Fuel "),Component.empty());sign.setText(new SignText(front,front,DyeColor.BLACK,false),SignTextSlot.FRONT);var back=List.<Component>of(Component.literal("Back"),Component.empty(),Component.empty(),Component.empty());sign.setText(new SignText(back,back,DyeColor.BLACK,false),SignTextSlot.BACK);packager.updateSignAddress();h.assertValueEqual(packager.signBasedAddress,"North Fuel","Front takes priority and trims lines");sign.setText(SignText.EMPTY,SignTextSlot.FRONT);packager.updateSignAddress();h.assertValueEqual(packager.signBasedAddress,"Back","Blank front falls back to back");h.succeed();}
    @GameTest public void redstoneButtonCooldownPreventsRepeatedPackingWithinFortyTicks(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.APPLE,64));var packager=packager(h);packager.activate();h.assertValueEqual(packager.buttonCooldown,40,"Button cooldown");tick(packager,20);packager.heldBox=ItemStack.EMPTY;source.setItem(0,new ItemStack(Items.CARROT,64));packager.activate();h.assertTrue(packager.heldBox.isEmpty(),"Cooldown suppresses short repeat");h.assertValueEqual(count(source,Items.CARROT),64,"No hidden extraction");h.succeed();}
    @GameTest public void queuedRequestsKeepCountsAddressesAndFragmentMetadata(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.APPLE,20));source.setItem(1,new ItemStack(Items.DIAMOND,10));var packager=packager(h);var requests=new ArrayList<PackagingRequest>();requests.add(PackagingRequest.create(new ItemStack(Items.APPLE),7,"Order A",2,new MutableBoolean(true),4,99,null));requests.add(PackagingRequest.create(new ItemStack(Items.DIAMOND),3,"Order A",2,new MutableBoolean(true),0,99,null));packager.attemptToSend(requests);h.assertTrue(requests.isEmpty(),"Both matching requests completed");h.assertValueEqual(count(source,Items.APPLE),13,"Exact apple request");h.assertValueEqual(count(source,Items.DIAMOND),7,"Exact diamond request");h.assertValueEqual(PackageItem.getAddress(packager.heldBox),"Order A","Fixed address");h.assertValueEqual(PackageItem.getOrderId(packager.heldBox),99,"Order ID");h.assertValueEqual(PackageItem.getLinkIndex(packager.heldBox),2,"Link");h.assertValueEqual(PackageItem.getIndex(packager.heldBox),4,"Fragment");h.assertTrue(PackageItem.isFinal(packager.heldBox)&&PackageItem.isFinalLink(packager.heldBox),"Final package and link");h.succeed();}
    @GameTest public void differentRequestAddressStartsSeparateOutputQueueEntry(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.APPLE,10));source.setItem(1,new ItemStack(Items.DIAMOND,10));var packager=packager(h);var requests=new ArrayList<PackagingRequest>(List.of(PackagingRequest.create(new ItemStack(Items.APPLE),5,"A",0,new MutableBoolean(true),0,1,null),PackagingRequest.create(new ItemStack(Items.DIAMOND),5,"B",0,new MutableBoolean(true),0,2,null)));packager.attemptToSend(requests);packager.attemptToSend(requests);h.assertTrue(requests.isEmpty(),"Both request groups completed");h.assertValueEqual(packager.queuedExitingPackages.size(),1,"Second output waits");h.assertValueEqual(PackageItem.getAddress(packager.heldBox),"A","First retained");h.assertValueEqual(PackageItem.getAddress(packager.queuedExitingPackages.getFirst().stack),"B","Second separately addressed");h.succeed();}
    @GameTest public void basinUnpackingBypassesUniqueInputRuleButKeepsOutputSlotsSeparate(GameTestHelper h){h.setBlock(TARGET,AllBlocks.BASIN);var basin=h.getBlockEntity(TARGET,com.simibubi.create.content.processing.basin.BasinBlockEntity.class);var packager=packager(h);var items=new ArrayList<ItemStack>();for(int i=0;i<9;i++)items.add(new ItemStack(Items.APPLE,64));var box=PackageItem.containingSlots(items);h.assertTrue(packager.unwrapBox(box,false),"Repeated equal inputs fill all basin slots");h.assertValueEqual(basin.inventory.inputs.stream().mapToLong(slot->slot.getAmount()).sum(),576L,"Nine full inputs");h.assertTrue(basin.inventory.outputs.stream().allMatch(slot->slot.isResourceBlank()),"Outputs never used for delivery");h.succeed();}
    @GameTest public void crafterOrderPlacesEachRecipeSlotAndAbortRestoresAllCrafters(GameTestHelper h){var state=AllBlocks.MECHANICAL_CRAFTER.defaultBlockState().setValue(MechanicalCrafterBlock.HORIZONTAL_FACING,Direction.SOUTH);h.setBlock(TARGET,state);h.setBlock(TARGET.east(),state);h.assertTrue(ConnectedInputHandler.toggleConnection(h.getLevel(),h.absolutePos(TARGET),h.absolutePos(TARGET.east())),"Joined inputs");var first=h.getBlockEntity(TARGET,MechanicalCrafterBlockEntity.class);var members=ConnectedInputHandler.getMembers(first);var items=List.of(new BigItemStack(new ItemStack(Items.APPLE),1),new BigItemStack(new ItemStack(Items.DIAMOND),1));var box=box(new ItemStack(Items.DIAMOND),new ItemStack(Items.APPLE));PackageItem.addOrderContext(box,PackageOrderWithCrafts.singleRecipe(items));var packager=packager(h);h.assertTrue(packager.unwrapBox(box,true),"Recipe delivery simulation");h.assertTrue(members.stream().allMatch(crafter->crafter.inventory.isResourceBlank()),"Simulation restores every input");h.assertTrue(packager.unwrapBox(box,false),"Recipe delivery commit");h.assertTrue(members.get(0).inventory.stack().is(Items.APPLE)&&members.get(1).inventory.stack().is(Items.DIAMOND),"Recipe order overrides box order");h.succeed();}
    @GameTest public void repackagerStoresIncomingBoxWithoutOpeningIt(GameTestHelper h){var destination=chest(h);var repackager=repackager(h);var box=box(new ItemStack(Items.APPLE,8));h.assertTrue(repackager.unwrapBox(box,true)&&destination.isEmpty(),"Simulation rolls back nested storage");h.assertTrue(repackager.unwrapBox(box,false),"Box accepted");h.assertTrue(PackageItem.isPackage(destination.getItem(0)),"Box remains packed");h.assertValueEqual(PackageItem.getContents(destination.getItem(0)).getFirst().getCount(),8,"Contents remain nested");h.succeed();}
    @GameTest public void repackagerWaitsForEveryFragmentAndThenMergesContents(GameTestHelper h){var source=chest(h);var first=box(new ItemStack(Items.APPLE,40));var second=box(new ItemStack(Items.APPLE,30));PackageItem.setOrder(first,77,0,true,0,false,null);PackageItem.setOrder(second,77,0,true,1,true,null);source.setItem(0,first);var repackager=repackager(h);repackager.attemptToSend(null);h.assertTrue(!source.isEmpty()&&repackager.queuedExitingPackages.isEmpty(),"Incomplete order retained");source.setItem(1,second);repackager.attemptToSend(null);h.assertTrue(source.isEmpty(),"Complete order extracted atomically");h.assertValueEqual(repackager.queuedExitingPackages.size(),1,"Merged into one outbound box");var output=repackager.queuedExitingPackages.getFirst().stack;h.assertValueEqual(PackageItem.getContents(output).stream().mapToInt(ItemStack::getCount).sum(),70,"All contents represented");h.assertTrue(PackageItem.isFinal(output),"Defragmented package final");h.succeed();}
    @GameTest public void repackagerCanForwardStandaloneBoxAfterAnIncompleteEarlierOrder(GameTestHelper h){var source=chest(h);var fragment=box(new ItemStack(Items.APPLE));PackageItem.setOrder(fragment,7,0,true,0,false,null);source.setItem(0,fragment);var standalone=box(new ItemStack(Items.DIAMOND,9));source.setItem(1,standalone.copy());var repackager=repackager(h);repackager.attemptToSend(null);h.assertTrue(ItemStack.isSameItemSameComponents(repackager.heldBox,standalone),"Standalone forwarded despite earlier incomplete order");h.assertFalse(source.getItem(0).isEmpty(),"Incomplete fragment retained");h.assertTrue(source.getItem(1).isEmpty(),"Only standalone consumed");h.succeed();}
    @GameTest public void recipeRepackWithMissingIngredientNeverConsumesPartialRecipe(GameTestHelper h){var source=chest(h);var fragment=box(new ItemStack(Items.APPLE,3));var context=new PackageOrderWithCrafts(new PackageOrder(List.of(new BigItemStack(new ItemStack(Items.APPLE),3))),List.of(new PackageOrderWithCrafts.CraftingEntry(new PackageOrder(List.of(new BigItemStack(new ItemStack(Items.APPLE),1),new BigItemStack(new ItemStack(Items.DIAMOND),1))),2)));PackageItem.setOrder(fragment,9,0,true,0,true,context);source.setItem(0,fragment);var repackager=repackager(h);repackager.attemptToSend(null);int apples=0;for(var output:repackager.queuedExitingPackages)apples+=PackageItem.getContents(output.stack).stream().filter(item->item.is(Items.APPLE)).mapToInt(item->item.getCount()*output.count).sum();h.assertValueEqual(apples,3,"Failed recipe attempts retain every available ingredient");h.assertTrue(repackager.queuedExitingPackages.stream().allMatch(item->item.count>0),"No zero-count phantom boxes");h.succeed();}
    @GameTest public void originalTagsAndQueuePersistThroughNativeBlockEntitySave(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.APPLE,9));var packager=packager(h);packager.attemptToSend(null);packager.queuedExitingPackages.add(new BigItemStack(box(new ItemStack(Items.DIAMOND,5)),2));tick(packager,7);var tag=packager.saveWithFullMetadata(h.getLevel().registryAccess());var restored=(PackagerBlockEntity)BlockEntity.loadStatic(packager.getBlockPos(),packager.getBlockState(),tag,h.getLevel().registryAccess());h.assertTrue(ItemStack.isSameItemSameComponents(packager.heldBox,restored.heldBox),"Held box saved");h.assertValueEqual(restored.animationTicks,13,"Remaining animation saved");h.assertValueEqual(restored.queuedExitingPackages.getFirst().count,2,"Output queue saved");h.succeed();}
    @GameTest public void summaryInvalidatesSortedCacheAfterNewArrivalsAndNativeVersions(GameTestHelper h){var source=chest(h);source.setItem(0,new ItemStack(Items.APPLE,8));var packager=packager(h);h.assertValueEqual(packager.getAvailableItems().getCountOf(new ItemStack(Items.APPLE)),8,"Initial stock");source.setItem(0,new ItemStack(Items.APPLE,11));h.assertValueEqual(packager.getAvailableItems().getCountOf(new ItemStack(Items.APPLE)),11,"Unversioned vanilla source rechecked");var summary=new InventorySummary();summary.add(new ItemStack(Items.APPLE),8);summary.getStacksByCount();summary.add(new ItemStack(Items.DIAMOND),9);h.assertValueEqual(summary.getStacksByCount().getFirst().stack.getItem(),Items.DIAMOND,"Mutation invalidates sort");h.succeed();}
}
